'use client'; import { useState } from 'react'; import { VendorFeedbackBanner, useVendorFeedback } from '@/components/vendor/ui/useVendorFeedback';
import { VendorModuleHeader, VendorStatusPill } from '@/components/vendor/ui/VendorModuleHeader';
import { vendorFieldClass, vendorLabelClass, VendorModal } from '@/components/vendor/ui/VendorModal';
import { supabase } from '@/lib/supabaseClient';
import { MOCK_COMPLIANCE_DOCS, MOCK_DASHBOARD_METRICS } from '@/lib/vendor/mock/data';
import { COMPLIANCE_UPLOAD_DOC_TYPES, DEFAULT_VENDOR_ID } from '@/lib/vendor-supabase/constants'; type UploadForm = { document_type: string; registration_number: string; expiry_date: string; file_url: string;
}; const emptyUpload: UploadForm = { document_type: 'Drug License', registration_number: '', expiry_date: '', file_url: '',
}; export function ComplianceWorkspace() { const score = MOCK_DASHBOARD_METRICS.complianceScore; const { feedback, showSuccess, showError } = useVendorFeedback(); const [uploadOpen, setUploadOpen] = useState(false); const [form, setForm] = useState<UploadForm>(emptyUpload); const [isSubmitting, setIsSubmitting] = useState(false); const handleUpload = async (e: React.FormEvent) => { e.preventDefault(); setIsSubmitting(true); const { error } = await supabase.from('compliance_documents').insert([ { vendor_id: DEFAULT_VENDOR_ID, document_type: form.document_type, registration_number: form.registration_number.trim() || null, expiry_date: form.expiry_date || null, file_url: form.file_url.trim() || null, status: 'PENDING_REVIEW', }, ]); setIsSubmitting(false); if (error) { showError(error.message); window.alert(`Error: ${error.message}`); return; } showSuccess('Compliance document uploaded for verification.'); setUploadOpen(false); setForm(emptyUpload); }; return ( <div className="space-y-6"> <VendorModuleHeader title="Compliance Center" description="Document locker, expiry alerts, verification status, compliance health score." actions={ <button type="button" onClick={() => setUploadOpen(true)} className="rounded-xl bg-vendor-secondary px-4 py-2 text-xs font-bold text-white hover:opacity-90"> Upload document </button> } /> <VendorFeedbackBanner feedback={feedback} /> <div className="flex flex-col items-center rounded-2xl border border-vendor-accent/20 bg-vendor-card p-6 border-vendor-accent/20 bg-vendor-card sm:flex-row sm:gap-8"> <div className="relative flex h-32 w-32 items-center justify-center rounded-full border-8 border-vendor-accent/40" role="img" aria-label={`Compliance health ${score} percent`} > <span className="text-3xl font-black text-vendor-secondary ">{score}%</span> </div> <div> <p className="text-sm font-black">Overall compliance health</p> <p className="mt-1 text-xs text-vendor-muted text-vendor-muted"> Automated verification against GSTN, CDSCO, and hospital audit policies. </p> </div> </div> <ul className="space-y-2"> {MOCK_COMPLIANCE_DOCS.map((doc) => ( <li key={doc.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-vendor-accent/20 bg-vendor-card px-4 py-3 border-vendor-accent/20 bg-vendor-card" > <div> <p className="text-sm font-bold">{doc.name}</p> <p className="text-xs text-vendor-muted"> {doc.type} {doc.expiryDate ? ` · exp ${doc.expiryDate}` : ''} </p> </div> <VendorStatusPill label={doc.status} tone={doc.status === 'Verified' ? 'success' : 'warning'} /> </li> ))} </ul> <VendorModal title="Upload compliance document" open={uploadOpen} onClose={() => setUploadOpen(false)} footer={ <> <button type="button" onClick={() => setUploadOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Cancel </button> <button type="submit" form="compliance-upload-form" disabled={isSubmitting} className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white disabled:opacity-60" > {isSubmitting ? 'Uploading…' : 'Submit document'} </button> </> } > <form id="compliance-upload-form" onSubmit={(e) => void handleUpload(e)} className="space-y-3"> <label className={vendorLabelClass}> Document type <select value={form.document_type} onChange={(e) => setForm((f) => ({ ...f, document_type: e.target.value }))} className={vendorFieldClass} > {COMPLIANCE_UPLOAD_DOC_TYPES.map((t) => ( <option key={t} value={t}> {t} </option> ))} </select> </label> <label className={vendorLabelClass}> Registration number <input required value={form.registration_number} onChange={(e) => setForm((f) => ({ ...f, registration_number: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> Expiry date <input type="date" required value={form.expiry_date} onChange={(e) => setForm((f) => ({ ...f, expiry_date: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> Document URL <input type="url" value={form.file_url} onChange={(e) => setForm((f) => ({ ...f, file_url: e.target.value }))} className={vendorFieldClass} /> </label> </form> </VendorModal> </div> );
}
